const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const subjects=['IQ','English','GK'],labels={IQ:'বুদ্ধিমত্তা',English:'ইংরেজি',GK:'সাধারণ জ্ঞান'},routes=[['dashboard','01','প্রস্তুতির চিত্র'],['tests','02','পরীক্ষা দিন'],['subjects','03','বিষয় ও দুর্বলতা'],['results','04','আমার ফলাফল'],['bank','05','প্রশ্নব্যাংক'],['import','06','আমদানি ও ব্যাকআপ']];let bank=[],raw=[],drafts=[],state,exam=null,viewResult=null,filter='সব',search='',page=1,timer;
function read(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}
state=read('airprep-v1',{results:[],custom:[],active:null});if(!Array.isArray(state.results)||!Array.isArray(state.custom))state={results:[],custom:[],active:null};
function save(){try{localStorage.setItem('airprep-v1',JSON.stringify(state));return true}catch{toast('সংরক্ষণ হয়নি। জায়গা খালি করুন বা ব্যাকআপ নিন।');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}
function title(a,b){return `<div class="pagetitle"><div class="eyebrow">প্রস্তুতির খাতা / ${a}</div><h1>${a}</h1><p class="muted">${b}</p></div>`}
function goto(r){location.hash=r}
function navigate(){clearInterval(timer);let route=location.hash.slice(1)||'dashboard';$('#nav').innerHTML=routes.map(([r,n,t])=>`<a href="#${r}" class="${r===route?'active':''}"><b>${n}</b>${t}</a>`).join('');({dashboard,tests,subjects:subjectPage,results,bank:bankPage,import:importPage,drafts:draftPage,exam:renderExam,review:reviewResult}[route]||dashboard)();window.scrollTo(0,0)}
function summary(){return Engine.analyse(state.results)}
function weak(){return Object.entries(summary()).filter(([s,a])=>a.total&&a.accuracy<70).sort((a,b)=>a[1].accuracy-b[1].accuracy)}
function dashboard(){let a=summary(),w=weak();$('#app').innerHTML=`<section class="hero"><div><div class="eyebrow">প্রতিটি ভুল, পরের প্রস্তুতির দিশা</div><h1>প্রস্তুতি হোক<br>লক্ষ্য ধরে।</h1><p>IQ, English ও GK অনুশীলন করুন। পরীক্ষা শেষে জানুন কোথায় আটকে যাচ্ছেন, তারপর সেখান থেকেই আবার শুরু করুন।</p><div class="row wrap" style="justify-content:flex-start"><button class="primary" onclick="goto('tests')">পরীক্ষা বেছে নিন ↗</button>${state.active?'<button onclick="resume()">অসমাপ্ত পরীক্ষা চালান</button>':'<button onclick="goto(\'bank\')">প্রশ্ন পড়ুন</button>'}</div></div><div class="flight" aria-label="উড্ডয়নের গতিপথের রেখাচিত্র"><svg viewBox="0 0 400 180" fill="none"><path d="M0 40H400M0 90H400M0 140H400M60 0V180M140 0V180M220 0V180M300 0V180M380 0V180" stroke="#dce2e9"/><path d="M18 152C90 152 92 104 156 110S254 54 330 37" stroke="#235bb2" stroke-width="3" stroke-dasharray="6 6"/><circle cx="18" cy="152" r="5" fill="#235bb2"/><path d="m318 36 46-15-26 40-3-20z" fill="#235bb2"/><circle cx="156" cy="110" r="5" fill="#235bb2"/><circle cx="247" cy="70" r="5" fill="#235bb2"/></svg><div class="caption"><span>অনুশীলন → মূল্যায়ন → রিটেস্ট</span><span>তিন বিষয়ে এগিয়ে চলা</span></div></div></section><div class="stats"><div class="stat">প্রস্তুত প্রশ্ন<div class="number">${bank.length}</div></div><div class="stat">বিষয়ভিত্তিক টেস্ট<div class="number">120</div></div><div class="stat">সম্পন্ন পরীক্ষা<div class="number">${state.results.length}</div></div></div><div class="grid"><section class="panel"><div class="row"><h2>আপনার বিষয়ভিত্তিক অবস্থান</h2><span class="tag">সর্বশেষ ৫টি / বিষয়</span></div>${subjects.map(s=>subjectRow(s,a[s])).join('')}</section><section class="panel"><h2>পরের পদক্ষেপ</h2>${w.length?`<p><b>${w[0][0]}</b>-এ সঠিক উত্তরের হার ${w[0][1].accuracy}%। আগে এই বিষয়টির ভুলগুলো অনুশীলন করুন।</p><button class="primary" onclick="retest('${w[0][0]}')">দুর্বলতার রিটেস্ট ↗</button>`:'<p class="muted">প্রথম পরীক্ষা শেষ হলে এখানেই আপনার প্রস্তুতির পরামর্শ দেখতে পাবেন। ৭০%-এর নিচে থাকলে বিষয়টিকে দুর্বল ধরা হবে।</p><button onclick="goto(\'tests\')">প্রথম পরীক্ষা দিন</button>'}<p style="margin-top:24px"><small>নম্বরের পাশাপাশি ব্যাখ্যাও পড়ুন। ছোট ভুলগুলোই পরের পরীক্ষায় বড় পার্থক্য আনে।</small></p></section></div><div class="notice">আমদানির অবস্থা: ২টি স্ক্যান PDF-এর ৬১ পৃষ্ঠা OCR করা হয়েছে। অপর ২টি PDF আকারের সীমায় আটকে আছে। যাচাই বাকি উৎস প্রশ্ন পরীক্ষায় ব্যবহার হয় না। বিস্তারিত প্রশ্নব্যাংকে।</div>`}
function subjectRow(s,a){return `<div class="subjectrow"><div class="row"><div><strong>${s}</strong> <small> / ${labels[s]}</small><div><small>${a.attempts}টি পরীক্ষা · ${bank.filter(q=>q.subject===s).length}টি প্রশ্ন</small></div></div><span>${a.accuracy===null?'এখনো পরীক্ষা হয়নি':a.accuracy+'% সঠিক'}</span></div><div class="bar"><i style="width:${a.accuracy??0}%"></i></div></div>`}
function tests(){let pool=subjects.flatMap(s=>Array.from({length:40},(_,i)=>({s,n:i+1}))).filter(x=>filter==='সব'||x.s===filter);$('#app').innerHTML=title('পরীক্ষা দিন','১২০টি বিষয়ভিত্তিক সেট। প্রতিটি সেটে ২৫টি প্রশ্ন, ১০০ নম্বর ও ৩০ মিনিট। একই ব্যাংকের প্রশ্ন বিভিন্ন সেটে পুনরায় আসতে পারে।')+`<div class="toolbar">${['সব',...subjects].map(s=>`<button class="${filter===s?'primary':''}" onclick="filter='${s}';tests()">${s}</button>`).join('')}</div><div class="tests">${pool.map(({s,n})=>`<article class="test"><div class="row"><span class="testnum">${s} / ${String(n).padStart(2,'0')}</span><span class="tag">${state.results.some(r=>r.testId===s+'-'+n)?'সম্পন্ন':'অনুশীলন'}</span></div><h3>${labels[s]} · টেস্ট ${n}</h3><p>২৫ প্রশ্ন · ১০০ নম্বর<br>৩০ মিনিট · ভুলে নম্বর কাটা নেই</p><button onclick="start('${s}',${n})">পরীক্ষা শুরু করুন ↗</button></article>`).join('')}</div>`}
function start(s,n,qs=null){if(state.active&&!confirm('একটি অসমাপ্ত পরীক্ষা আছে। সেটি বাদ দিয়ে নতুন পরীক্ষা শুরু করবেন?'))return;let questions=qs||Engine.select(bank,s,n*997+subjects.indexOf(s)*311);if(!questions.length){toast('প্রশ্ন পাওয়া যায়নি');return}exam={subject:s,testId:qs?s+'-retest':s+'-'+n,name:qs?'দুর্বলতার রিটেস্ট':`টেস্ট ${n}`,questions,answers:{},index:0,deadline:Date.now()+30*60000,started:Date.now()};state.active=exam;if(!save())return;goto('exam');if(location.hash==='#exam')renderExam()}
function resume(){exam=state.active;if(exam)goto('exam')}
function persist(){state.active=exam;save()}
function renderExam(){exam=exam||state.active;if(!exam){goto('tests');return}if(Date.now()>=exam.deadline){submitExam(true);return}let q=exam.questions[exam.index];$('#app').innerHTML=`<div class="row pagetitle"><div><div class="eyebrow">${exam.subject} / ${esc(exam.name)}</div><h1>একটি করে, মন দিয়ে।</h1></div><div><small>অবশিষ্ট সময়</small><div class="timer" id="clock"></div></div></div><div class="exam"><section><div class="panel"><div class="row"><span class="tag">প্রশ্ন ${exam.index+1} / ${exam.questions.length}</span><small>${esc(q.topic)} · ${(100/exam.questions.length).toFixed(1)} নম্বর</small></div><h2 class="question">${esc(q.question)}</h2><div class="options">${q.options.map((o,i)=>`<button class="option ${exam.answers[q.id]===i?'selected':''}" aria-pressed="${exam.answers[q.id]===i}" onclick="answer(${i})"><b>${'ABCD'[i]}</b><span>${esc(o)}</span></button>`).join('')}</div><div class="row" style="margin-top:24px"><button ${exam.index===0?'disabled':''} onclick="step(-1)">← আগের প্রশ্ন</button><button ${exam.index===exam.questions.length-1?'disabled':''} onclick="step(1)">পরের প্রশ্ন →</button></div></div><button onclick="goto('dashboard')">বিরতি / পরে চালাব</button></section><section class="panel"><h3>উত্তরের খাতা</h3><p class="muted">${Object.keys(exam.answers).length} / ${exam.questions.length}টি উত্তর দেওয়া হয়েছে</p><div class="palette">${exam.questions.map((x,i)=>`<button class="${exam.answers[x.id]!==undefined?'done':''} ${i===exam.index?'current':''}" onclick="jump(${i})" aria-label="প্রশ্ন ${i+1}">${i+1}</button>`).join('')}</div><p style="margin-top:24px"><small>উত্তর বদলাতে অপশনটি আবার বেছে নিন। সময় শেষে স্বয়ংক্রিয়ভাবে জমা হবে।</small></p><button class="primary" onclick="submitExam()">উত্তর জমা দিন</button></section></div>`;clearInterval(timer);tick();timer=setInterval(tick,1000)}
function tick(){if(!exam)return;let sec=Math.max(0,Math.ceil((exam.deadline-Date.now())/1000));if($('#clock'))$('#clock').textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');if(!sec)submitExam(true)}
function answer(i){exam.answers[exam.questions[exam.index].id]=i;persist();renderExam()}function step(n){jump(exam.index+n)}function jump(i){exam.index=i;persist();renderExam()}
function submitExam(auto=false){if(!exam)return;if(!auto&&!confirm(`${exam.questions.length-Object.keys(exam.answers).length}টি প্রশ্ন অনুত্তরিত। পরীক্ষা জমা দেবেন?`))return;clearInterval(timer);let result={id:'r'+Date.now(),subject:exam.subject,testId:exam.testId,name:exam.name,date:new Date().toISOString(),questions:exam.questions,answers:exam.answers,duration:Math.round((Date.now()-exam.started)/1000),...Engine.grade(exam.questions,exam.answers)};state.results.push(result);state.active=null;exam=null;save();viewResult=result.id;goto('review');if(location.hash==='#review')reviewResult()}
function retest(s){let rows=state.results.filter(r=>r.subject===s).slice(-5),wrong=new Set();for(const r of rows)for(const q of r.questions){if(r.answers[q.id]!==q.answer)wrong.add(q.id);else wrong.delete(q.id)}let topicStats=summary()[s].topics;let topics=Object.entries(topicStats).filter(([k,v])=>v.right/v.total<.7).map(([k])=>k);let qs=Engine.shuffle(bank.filter(q=>q.subject===s&&(wrong.has(q.id)||topics.includes(q.topic))),Date.now());if(!qs.length){toast('ভুল প্রশ্ন নেই। নিয়মিত টেস্ট দিয়ে শুরু করুন।');return}start(s,0,qs.slice(0,25))}
function subjectPage(){let a=summary();$('#app').innerHTML=title('বিষয় ও দুর্বলতা','সর্বশেষ পাঁচটি পরীক্ষার উত্তর দিয়ে বিশ্লেষণ। ৭০%-এর নিচে হলে আরও অনুশীলন দরকার; কোনো পরীক্ষা না হলে দুর্বলতা নির্ধারণ করা হয় না।')+subjects.map(s=>`<section class="panel">${subjectRow(s,a[s])}<div class="toolbar"><button onclick="filter='${s}';goto('tests')">${s} টেস্ট দেখুন</button><button class="primary" onclick="retest('${s}')">ভুল ও দুর্বল টপিকের রিটেস্ট</button></div>${Object.entries(a[s].topics).map(([t,v])=>`<div class="row subjectrow"><span>${esc(t)}</span><span class="${v.right/v.total<.7?'danger':'answer'}">${v.right} / ${v.total} সঠিক · ${Math.round(v.right/v.total*100)}%</span></div>`).join('')}</section>`).join('')}
function results(){$('#app').innerHTML=title('আমার ফলাফল','সব পরীক্ষা, নম্বর ও ব্যাখ্যা এক জায়গায়। অন্য ডিভাইসে নিতে আমদানি ও ব্যাকআপ পৃষ্ঠা ব্যবহার করুন।')+(state.results.length?`<div class="panel tablewrap"><table><thead><tr><th>পরীক্ষা</th><th>তারিখ</th><th>নম্বর</th><th>সঠিক</th><th>খাতা</th></tr></thead><tbody>${[...state.results].reverse().map(r=>`<tr><td>${esc(r.subject)} · ${esc(r.name)}</td><td>${new Date(r.date).toLocaleString('bn-BD',{timeZone:'Asia/Dhaka'})}</td><td>${r.score} / 100</td><td>${r.right} / ${r.total}</td><td><button onclick="viewResult=state.results[${state.results.indexOf(r)}].id;goto('review')">দেখুন ↗</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="panel empty">এখনো কোনো পরীক্ষা শেষ হয়নি।<p><button onclick="goto(\'tests\')">প্রথম পরীক্ষা দিন</button></p></div>')}
function reviewResult(){let r=state.results.find(r=>r.id===viewResult)||state.results.at(-1);if(!r){goto('results');return}$('#app').innerHTML=title(`${esc(r.subject)} · ${esc(r.name)}`,`পরীক্ষার নম্বর ${r.score} / 100। সঠিক ${r.right}টি, ভুল ${r.total-r.right- r.questions.filter(q=>r.answers[q.id]===undefined).length}টি, অনুত্তরিত ${r.questions.filter(q=>r.answers[q.id]===undefined).length}টি।`)+`<div class="toolbar"><button class="primary" onclick="retest('${r.subject}')">দুর্বলতার রিটেস্ট</button><button onclick="goto('subjects')">দুর্বলতা বিশ্লেষণ</button><button onclick="goto('results')">সব ফলাফল</button></div>`+r.questions.map((q,i)=>`<article class="review ${r.answers[q.id]===q.answer?'':'wrong'}"><small>প্রশ্ন ${i+1} · ${esc(q.topic)}</small><h3>${esc(q.question)}</h3><p>আপনার উত্তর: ${r.answers[q.id]===undefined?'অনুত্তরিত':esc(q.options[r.answers[q.id]])}<br><strong class="answer">সঠিক উত্তর: ${esc(q.options[q.answer])}</strong></p><p>${esc(q.explanation)}</p><small>উৎস: ${esc(q.source||'নিজস্ব আমদানি')}${q.page?' · পৃষ্ঠা '+q.page:''}</small></article>`).join('')}
function bankPage(){let qs=bank.filter(q=>(filter==='সব'||q.subject===filter)&&(q.question+' '+q.topic).toLowerCase().includes(search.toLowerCase()));let pages=Math.max(1,Math.ceil(qs.length/20));page=Math.min(page,pages);$('#app').innerHTML=title('প্রশ্নব্যাংক','যাচাই করা MCQ, সঠিক উত্তর ও ব্যাখ্যা। সম্পূরক অনুশীলন এবং PDF থেকে নেওয়া প্রশ্নের উৎস আলাদাভাবে দেখানো আছে।')+`<div class="toolbar"><input type="search" placeholder="প্রশ্ন বা টপিক খুঁজুন" aria-label="প্রশ্ন খুঁজুন" value="${esc(search)}" onchange="search=this.value;page=1;bankPage()"><select aria-label="বিষয়" onchange="filter=this.value;page=1;bankPage()">${['সব',...subjects].map(s=>`<option ${filter===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="panel"><div class="row"><h2>${qs.length}টি প্রশ্ন</h2><span class="tag">পৃষ্ঠা ${page} / ${pages}</span></div>${qs.slice((page-1)*20,page*20).map(q=>`<details><summary><span class="tag">${q.subject}</span> ${esc(q.question)}</summary><ol type="A">${q.options.map(o=>`<li>${esc(o)}</li>`).join('')}</ol><p class="answer">সঠিক: ${esc(q.options[q.answer])}</p><p>${esc(q.explanation)}</p><small>${esc(q.source)}${q.page?' · পৃষ্ঠা '+q.page:''}</small></details>`).join('')}<div class="toolbar"><button ${page===1?'disabled':''} onclick="page--;bankPage()">← আগের</button><button ${page===pages?'disabled':''} onclick="page++;bankPage()">পরের →</button></div></div><section class="panel"><h2>PDF উৎস ও যাচাইয়ের তালিকা</h2><button onclick="goto('drafts')">১,৩৪৪টি OCR খসড়া যাচাই করুন ↗</button><p class="muted">${raw.length}টি OCR অংশ রাখা আছে। শব্দ, উত্তর ও ব্যাখ্যা যাচাই ছাড়া এগুলো পরীক্ষার প্রশ্ন নয়। ব্যক্তিগত পরিচয়পত্র ও আবেদন ফরম বাদ দেওয়া হয়েছে।</p><select aria-label="উৎস পৃষ্ঠা" id="sourceSelect" onchange="showSource(this.value)"><option value="">উৎস পৃষ্ঠা বেছে নিন</option>${raw.map((r,i)=>`<option value="${i}">${esc(r.source)} · পৃষ্ঠা ${r.page}</option>`).join('')}</select><div id="sourceView"></div></section>`}
function showSource(i){if(i===''){$('#sourceView').innerHTML='';return}const r=raw[+i];$('#sourceView').innerHTML=`<div class="notice">OCR খসড়া — ভুল থাকতে পারে। মূল পৃষ্ঠার সঙ্গে মিলিয়ে নিন।</div><p><a href="sources/${r.image}" target="_blank" rel="noopener">মূল স্ক্যান দেখুন ↗</a></p><pre style="white-space:pre-wrap;font:inherit">${esc(r.text)}</pre><button onclick="goto('import')">যাচাই করে MCQ যোগ করুন</button>`}
function download(name,data){let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function importPage(){$('#app').innerHTML=title('আমদানি ও ব্যাকআপ','সহজ JSON ফাইলে প্রশ্ন ও ফলাফল রাখুন। ব্যাকআপ নিয়মিত ডাউনলোড করলে ব্রাউজারের ডেটা মুছে গেলেও ফেরত পাওয়া যাবে।')+`<div class="grid"><section class="panel"><h2>নতুন MCQ যোগ করুন</h2><form id="addForm" class="formgrid"><label>বিষয়<select name="subject">${subjects.map(s=>`<option>${s}</option>`).join('')}</select></label><label>টপিক<input name="topic" required></label><label>প্রশ্ন<input name="question" required></label>${[0,1,2,3].map(i=>`<label>অপশন ${'ABCD'[i]}<input name="o${i}" required></label>`).join('')}<label>সঠিক উত্তর<select name="answer">${[0,1,2,3].map(i=>`<option value="${i}">${'ABCD'[i]}</option>`).join('')}</select></label><label>পূর্ণ ব্যাখ্যা<input name="explanation" required></label><label>উৎস / PDF পৃষ্ঠা<input name="source" required></label><button class="primary">যাচাই করা প্রশ্ন যোগ করুন</button></form></section><section><div class="panel"><h2>সম্পূর্ণ ব্যাকআপ</h2><p class="muted">ফলাফল, নিজের আমদানি করা প্রশ্ন ও অসমাপ্ত পরীক্ষা অন্তর্ভুক্ত থাকবে। ব্রাউজার বদলালে এই ফাইল ফেরত আনুন।</p><button onclick="download('airprep-backup.json',{version:1,state})">ব্যাকআপ ডাউনলোড</button><p><label>ব্যাকআপ ফেরত আনুন<input type="file" accept=".json" onchange="restore(this.files[0])"></label></p></div><div class="panel"><h2>একসঙ্গে প্রশ্ন আমদানি</h2><p>JSON array দিন। উত্তর ০–৩: A=0, B=1, C=2, D=3। শুধু IQ, English ও GK গ্রহণ করা হবে। PDF আমদানি স্বয়ংক্রিয় নয়; OCR করে যাচাই করা JSON লাগবে।</p><button onclick="download('questions-template.json',[{id:'custom-001',subject:'English',topic:'Article',question:'He is ___ honest man.',options:['a','an','the','no article'],answer:1,explanation:'Honest শব্দে h অনুচ্চারিত; vowel sound-এর আগে an বসে।',source:'নিজস্ব প্রশ্ন'}])">নমুনা JSON</button><p><input aria-label="প্রশ্ন JSON ফাইল" type="file" accept=".json" onchange="importQuestions(this.files[0])"></p><button onclick="download('all-questions.json',bank)">পুরো প্রশ্নব্যাংক ডাউনলোড</button></div><div class="notice">এই সংস্করণে অ্যাকাউন্ট বা সার্ভার ডেটাবেস নেই। একই ব্রাউজারে ডেটা থাকে; স্বয়ংক্রিয়ভাবে ডিভাইসের মধ্যে sync হয় না।</div></section></div>`;$('#addForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),q={id:'custom-'+Date.now(),subject:f.get('subject'),topic:f.get('topic'),question:f.get('question'),options:[0,1,2,3].map(i=>f.get('o'+i)),answer:+f.get('answer'),explanation:f.get('explanation'),source:f.get('source')};if(!Engine.valid(q)){toast('চারটি আলাদা অপশন ও সব তথ্য দিন');return}state.custom.push(q);bank.push(q);save();toast('প্রশ্ন যোগ হয়েছে');e.target.reset()}}
async function parseFile(f){if(!f)throw Error('ফাইল বেছে নিন');if(f.size>15000000)throw Error('JSON ফাইল ১৫ MB-এর মধ্যে দিন');return JSON.parse(await f.text())}
async function importQuestions(f){try{let qs=await parseFile(f);if(!Array.isArray(qs)||!qs.length||!qs.every(Engine.valid))throw Error('JSON schema মিলছে না; নমুনা ফাইল দেখুন');let ids=new Set(bank.map(q=>q.id)),added=[];for(let q of qs){if(!ids.has(q.id)){added.push(q);ids.add(q.id)}}state.custom.push(...added);bank.push(...added);save();toast(added.length+'টি নতুন প্রশ্ন আমদানি হয়েছে')}catch(e){toast(e.message)}}
async function restore(f){try{let data=await parseFile(f),s=data.state;if(data.version!==1||!s||!Array.isArray(s.results)||!Array.isArray(s.custom)||!s.custom.every(Engine.valid)||!s.results.every(r=>typeof r.id==='string'&&subjects.includes(r.subject)&&Array.isArray(r.questions)&&r.questions.length&&r.questions.every(Engine.valid)&&r.answers&&r.topics&&Number.isFinite(r.score)&&!isNaN(Date.parse(r.date))))throw Error('সঠিক ব্যাকআপ ফাইল নয়');if(s.active&&(!Array.isArray(s.active.questions)||!s.active.questions.every(Engine.valid)||!Number.isFinite(s.active.deadline)))throw Error('অসমাপ্ত পরীক্ষার ডেটা সঠিক নয়');if(!confirm('বর্তমান ডেটার জায়গায় ব্যাকআপের ডেটা বসবে। চালিয়ে যাবেন?'))return;state=s;save();location.reload()}catch(e){toast(e.message)}}
window.addEventListener('hashchange',navigate);$('#date').textContent=new Date().toLocaleDateString('bn-BD',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Dhaka'});
Promise.all([fetch('data/questions.json').then(r=>{if(!r.ok)throw Error();return r.json()}),fetch('data/sources.json').then(r=>{if(!r.ok)throw Error();return r.json()}),fetch('data/drafts.json').then(r=>r.json())]).then(([qs,rs,ds])=>{bank=[...qs,...state.custom.filter(q=>!qs.some(x=>x.id===q.id))];raw=rs;drafts=ds;navigate()}).catch(()=>{$('#app').innerHTML='<div class="notice">ডেটা লোড হয়নি। ফাইল সরাসরি না খুলে README অনুযায়ী ওয়েব সার্ভার চালান।</div>'});

function draftPage(){const list=drafts.filter(d=>d.text.includes(search));let pages=Math.max(1,Math.ceil(list.length/20));page=Math.min(page,pages);$('#app').innerHTML=title('OCR খসড়া যাচাই','এগুলো এখনো পরীক্ষার MCQ নয়। উৎস দেখে প্রশ্ন, চার অপশন, সঠিক উত্তর ও ব্যাখ্যা লিখে যোগ করুন।')+`<div class="toolbar"><input type="search" aria-label="খসড়া খুঁজুন" placeholder="খসড়া খুঁজুন" value="${esc(search)}" onchange="search=this.value;page=1;draftPage()"><button onclick="goto('bank')">প্রশ্নব্যাংক</button></div><div class="panel"><p>${list.length}টি খসড়া · পৃষ্ঠা ${page} / ${pages}</p>${list.slice((page-1)*20,page*20).map(d=>`<details><summary>${esc(d.text.slice(0,100))}…</summary><p>${esc(d.text)}</p><small>${esc(d.source)} · পৃষ্ঠা ${d.page} · যাচাই বাকি</small><p><a href="sources/${raw.find(r=>r.source===d.source&&r.page===d.page)?.image}" target="_blank" rel="noopener">মূল পৃষ্ঠা দেখুন ↗</a></p><button onclick="editDraft(${drafts.indexOf(d)})">MCQ তৈরি করুন</button></details>`).join('')}<div class="toolbar"><button ${page===1?'disabled':''} onclick="page--;draftPage()">আগের</button><button ${page===pages?'disabled':''} onclick="page++;draftPage()">পরের</button></div></div>`}
function editDraft(i){importPage();const d=drafts[i],f=$('#addForm');f.elements.subject.value=d.subject;f.elements.question.value=d.text;f.elements.source.value=d.source+' · পৃষ্ঠা '+d.page;$('#app').insertAdjacentHTML('afterbegin','<div class="notice">OCR লেখা প্রশ্ন ঘরে দেওয়া হয়েছে। উত্তর আলাদা করে অপশন, সঠিক উত্তর ও ব্যাখ্যা লিখুন। মূল পৃষ্ঠার সঙ্গে মিলিয়ে নিন।</div>')}
